document.addEventListener("DOMContentLoaded", function () {
  var e = document.getElementById("text-a"),
    t = document.getElementById("text-b"),
    n = document.getElementById("compare-btn"),
    d = document.getElementById("reset-btn"),
    o = document.getElementById("copy-btn"),
    a = document.getElementById("result-area"),
    i = document.getElementById("result-content"),
    c = document.getElementById("stats"),
    statusBadge = document.getElementById("status-badge"),
    resultIconWrap = document.getElementById("result-icon-wrap"),
    resultHeading = document.getElementById("result-heading"),
    resultSub = document.getElementById("result-sub"),
    summaryStatus = document.getElementById("summary-status"),
    statSimilarityWords = document.getElementById("stat-similarity-words"),
    statLinesCompared = document.getElementById("stat-lines-compared"),
    statChanged = document.getElementById("stat-changed"),
    similarityPct = document.getElementById("similarity-pct"),
    similarityFill = document.getElementById("similarity-fill"),
    statAdded = document.getElementById("stat-added"),
    statRemoved = document.getElementById("stat-removed"),
    statModified = document.getElementById("stat-modified"),
    statUnchanged = document.getElementById("stat-unchanged"),
    originalLines = document.getElementById("original-lines"),
    modifiedLines = document.getElementById("modified-lines"),
    originalLineCount = document.getElementById("original-line-count"),
    modifiedLineCount = document.getElementById("modified-line-count"),
    diffPanels = document.getElementById("diff-panels"),
    downloadBtn = document.getElementById("download-btn"),
    compareAnotherBtn = document.getElementById("compare-another-btn"),
    actionBar = document.getElementById("action-bar");

  var lastDiffResult = null;

  // ── Utility ──────────────────────────────────────────────────────────
  function escHtml(s) {
    return s
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");
  }

  function showToast(msg, type) {
    var existing = document.querySelector(".toast");
    if (existing) existing.remove();
    var toast = document.createElement("div");
    toast.className = "toast " + (type || "info");
    toast.textContent = msg;
    document.body.appendChild(toast);
    requestAnimationFrame(function () {
      requestAnimationFrame(function () {
        toast.classList.add("show");
      });
    });
    setTimeout(function () {
      toast.classList.remove("show");
      setTimeout(function () { toast.remove(); }, 300);
    }, 3000);
  }

  function setStatus(state) {
    statusBadge.className = "status-badge " + state;
    var labels = { ready: "Ready", processing: "Processing\u2026", done: "Done", error: "Error" };
    statusBadge.textContent = labels[state] || "";
  }

  function showResults() {
    a.classList.add("show");
    a.style.display = "block";
  }

  function hideResults() {
    a.classList.remove("show");
    a.style.display = "none";
  }

  function countWords(text) {
    var trimmed = text.trim();
    if (!trimmed) return 0;
    return trimmed.split(/\s+/).length;
  }

  // ── LCS Algorithm (preserved exactly) ────────────────────────────────
  function lcs(arrA, arrB) {
    var lenA = arrA.length,
      lenB = arrB.length,
      dp = [],
      row,
      col;
    for (row = 0; row <= lenA; row++) {
      dp[row] = [];
      for (col = 0; col <= lenB; col++) {
        if (row === 0 || col === 0) {
          dp[row][col] = 0;
        } else if (arrA[row - 1] === arrB[col - 1]) {
          dp[row][col] = dp[row - 1][col - 1] + 1;
        } else {
          dp[row][col] = Math.max(dp[row - 1][col], dp[row][col - 1]);
        }
      }
    }
    var result = [];
    row = lenA;
    col = lenB;
    while (row > 0 && col > 0) {
      if (arrA[row - 1] === arrB[col - 1]) {
        result.unshift({ type: "unchanged", text: arrA[row - 1] });
        row--;
        col--;
      } else if (dp[row - 1][col] > dp[row][col - 1]) {
        row--;
      } else {
        col--;
      }
    }
    return result;
  }

  // ── Build flat diff from LCS result ──────────────────────────────────
  function buildFlatDiff(linesA, linesB, lcsResult) {
    var diff = [],
      idxA = 0,
      idxB = 0,
      idxL = 0;
    while (idxA < linesA.length || idxB < linesB.length) {
      if (
        idxL < lcsResult.length &&
        idxA < linesA.length &&
        idxB < linesB.length &&
        linesA[idxA] === lcsResult[idxL].text &&
        linesB[idxB] === lcsResult[idxL].text
      ) {
        diff.push({ type: "unchanged", textA: linesA[idxA], textB: linesB[idxB] });
        idxA++;
        idxB++;
        idxL++;
      } else if (idxA < linesA.length && (idxL >= lcsResult.length || linesA[idxA] !== lcsResult[idxL].text)) {
        diff.push({ type: "removed", textA: linesA[idxA], textB: "" });
        idxA++;
      } else if (idxB < linesB.length) {
        diff.push({ type: "added", textA: "", textB: linesB[idxB] });
        idxB++;
      }
    }
    return diff;
  }

  // ── Pair removed+added into "modified" ───────────────────────────────
  function pairLines(flatDiff) {
    var paired = [];
    var i = 0;

    // Step 1: pair consecutive removed+added blocks
    while (i < flatDiff.length) {
      if (flatDiff[i].type === "removed") {
        var removes = [];
        while (i < flatDiff.length && flatDiff[i].type === "removed") {
          removes.push(flatDiff[i]);
          i++;
        }
        var adds = [];
        while (i < flatDiff.length && flatDiff[i].type === "added") {
          adds.push(flatDiff[i]);
          i++;
        }
        var pairCount = Math.min(removes.length, adds.length);
        for (var p = 0; p < pairCount; p++) {
          paired.push({ type: "modified", textA: removes[p].textA, textB: adds[p].textB });
        }
        for (var r = pairCount; r < removes.length; r++) {
          paired.push({ type: "removed", textA: removes[r].textA, textB: "" });
        }
        for (var a = pairCount; a < adds.length; a++) {
          paired.push({ type: "added", textA: "", textB: adds[a].textB });
        }
      } else {
        paired.push(flatDiff[i]);
        i++;
      }
    }

    // Step 2: match remaining unmatched removals/additions across unchanged barriers
    var unrem = [], unadd = [];
    for (var k = 0; k < paired.length; k++) {
      if (paired[k].type === "removed") unrem.push(k);
      else if (paired[k].type === "added") unadd.push(k);
    }

    if (unrem.length > 0 && unadd.length > 0) {
      function lineSim(a, b) {
        if (!a && !b) return 1;
        if (!a || !b) return 0;
        var maxLen = Math.max(a.length, b.length);
        if (maxLen === 0) return 1;
        var shorter = Math.min(a.length, b.length);
        var same = 0;
        for (var p = 0; p < shorter; p++) {
          if (a[p] === b[p]) same++;
          else break;
        }
        return same / maxLen;
      }

      var matchedR = {}, matchedA = {};
      var pairs = [];
      for (var ri = 0; ri < unrem.length; ri++) {
        for (var ai = 0; ai < unadd.length; ai++) {
          var sim = lineSim(paired[unrem[ri]].textA, paired[unadd[ai]].textB);
          if (sim > 0) pairs.push({ ri: ri, ai: ai, sim: sim });
        }
      }
      pairs.sort(function (x, y) { return y.sim - x.sim; });
      for (var q = 0; q < pairs.length; q++) {
        if (!matchedR[pairs[q].ri] && !matchedA[pairs[q].ai]) {
          matchedR[pairs[q].ri] = true;
          matchedA[pairs[q].ai] = true;
          paired[unrem[pairs[q].ri]] = {
            type: "modified",
            textA: paired[unrem[pairs[q].ri]].textA,
            textB: paired[unadd[pairs[q].ai]].textB
          };
          paired[unadd[pairs[q].ai]] = null;
        }
      }
      paired = paired.filter(function (x) { return x !== null; });
    }

    return paired;
  }

  // ── Word-level diff (inline highlighting) ────────────────────────────
  function wordDiffHtml(oldText, newText) {
    var oldWords = oldText.split(/(\s+)/);
    var newWords = newText.split(/(\s+)/);
    var dp = [];
    var wLen = oldWords.length,
      hLen = newWords.length;
    var r, c;
    for (r = 0; r <= wLen; r++) {
      dp[r] = [];
      for (c = 0; c <= hLen; c++) {
        if (r === 0 || c === 0) {
          dp[r][c] = 0;
        } else if (oldWords[r - 1] === newWords[c - 1]) {
          dp[r][c] = dp[r - 1][c - 1] + 1;
        } else {
          dp[r][c] = Math.max(dp[r - 1][c], dp[r][c - 1]);
        }
      }
    }
    var ops = [];
    r = wLen;
    c = hLen;
    while (r > 0 && c > 0) {
      if (oldWords[r - 1] === newWords[c - 1]) {
        ops.unshift({ type: "same", text: oldWords[r - 1] });
        r--;
        c--;
      } else if (dp[r - 1][c] >= dp[r][c - 1]) {
        ops.unshift({ type: "del", text: oldWords[r - 1] });
        r--;
      } else {
        ops.unshift({ type: "add", text: newWords[c - 1] });
        c--;
      }
    }
    while (r > 0) { ops.unshift({ type: "del", text: oldWords[r - 1] }); r--; }
    while (c > 0) { ops.unshift({ type: "add", text: newWords[c - 1] }); c--; }

    var origHtml = "",
      modHtml = "";
    for (var k = 0; k < ops.length; k++) {
      var op = ops[k];
      var safe = escHtml(op.text);
      if (op.type === "same") {
        origHtml += safe;
        modHtml += safe;
      } else if (op.type === "del") {
        origHtml += '<span class="w-removed">' + safe + "</span>";
      } else {
        modHtml += '<span class="w-added">' + safe + "</span>";
      }
    }
    return { origHtml: origHtml, modHtml: modHtml };
  }

  // ── Character-level LCS for accurate similarity ──────────────────────
  function charLcsLen(a, b) {
    var lenA = a.length,
      lenB = b.length;
    if (lenA === 0 || lenB === 0) return 0;
    var prev = new Array(lenB + 1);
    var curr = new Array(lenB + 1);
    var i, j;
    for (j = 0; j <= lenB; j++) prev[j] = 0;
    for (i = 1; i <= lenA; i++) {
      curr[0] = 0;
      for (j = 1; j <= lenB; j++) {
        if (a[i - 1] === b[j - 1]) {
          curr[j] = prev[j - 1] + 1;
        } else {
          curr[j] = prev[j] > curr[j - 1] ? prev[j] : curr[j - 1];
        }
      }
      var tmp = prev;
      prev = curr;
      curr = tmp;
    }
    return prev[lenB];
  }

  // ── Similarity calculation (Dice coefficient on character LCS) ────────
  function calcSimilarity(textA, textB) {
    if (textA.length === 0 && textB.length === 0) return 100;
    if (textA.length === 0 || textB.length === 0) return 0;
    var lcsLen = charLcsLen(textA, textB);
    return Math.round((2 * lcsLen * 100) / (textA.length + textB.length));
  }

  // ── Render side-by-side panels ───────────────────────────────────────
  function renderSideBySide(paired) {
    var origHtml = "",
      modHtml = "",
      origNum = 0,
      modNum = 0;

    for (var k = 0; k < paired.length; k++) {
      var line = paired[k];

      if (line.type === "unchanged") {
        origNum++;
        modNum++;
        var escaped = escHtml(line.textA);
        origHtml += '<div class="diff-line unchanged"><span class="diff-line-marker">&nbsp;</span><span class="diff-line-num">' + origNum + '</span><span class="diff-line-content">' + escaped + "</span></div>";
        modHtml += '<div class="diff-line unchanged"><span class="diff-line-marker">&nbsp;</span><span class="diff-line-num">' + modNum + '</span><span class="diff-line-content">' + escaped + "</span></div>";
      } else if (line.type === "modified") {
        origNum++;
        modNum++;
        var wd = wordDiffHtml(line.textA, line.textB);
        origHtml += '<div class="diff-line modified"><span class="diff-line-marker">~</span><span class="diff-line-num">' + origNum + '</span><span class="diff-line-content">' + (wd.origHtml || "&nbsp;") + "</span></div>";
        modHtml += '<div class="diff-line modified"><span class="diff-line-marker">~</span><span class="diff-line-num">' + modNum + '</span><span class="diff-line-content">' + (wd.modHtml || "&nbsp;") + "</span></div>";
      } else if (line.type === "removed") {
        origNum++;
        origHtml += '<div class="diff-line removed"><span class="diff-line-marker">\u2212</span><span class="diff-line-num">' + origNum + '</span><span class="diff-line-content">' + escHtml(line.textA) + "</span></div>";
        modHtml += '<div class="diff-line empty"><span class="diff-line-marker">&nbsp;</span><span class="diff-line-num"></span><span class="diff-line-content">&nbsp;</span></div>';
      } else if (line.type === "added") {
        modNum++;
        modHtml += '<div class="diff-line added"><span class="diff-line-marker">+</span><span class="diff-line-num">' + modNum + '</span><span class="diff-line-content">' + escHtml(line.textB) + "</span></div>";
        origHtml += '<div class="diff-line empty"><span class="diff-line-marker">&nbsp;</span><span class="diff-line-num"></span><span class="diff-line-content">&nbsp;</span></div>';
      }
    }

    originalLines.innerHTML = origHtml;
    modifiedLines.innerHTML = modHtml;
    originalLineCount.textContent = origNum + " lines";
    modifiedLineCount.textContent = modNum + " lines";
  }

  // ── Render unified diff (mobile fallback) ────────────────────────────
  function renderUnified(paired) {
    var html = "";
    var origNum = 0,
      modNum = 0;
    for (var k = 0; k < paired.length; k++) {
      var line = paired[k];
      if (line.type === "unchanged") {
        origNum++;
        var escaped = escHtml(line.textA);
        html += '<div class="diff-line unchanged"><span class="diff-line-marker">&nbsp;</span><span class="diff-line-num">' + origNum + '</span><span class="diff-line-content">' + escaped + "</span></div>";
      } else if (line.type === "modified") {
        origNum++;
        modNum++;
        var wd = wordDiffHtml(line.textA, line.textB);
        html += '<div class="diff-line modified"><span class="diff-line-marker">~</span><span class="diff-line-num">' + origNum + '</span><span class="diff-line-content">' + (wd.origHtml || "&nbsp;") + "</span></div>";
        html += '<div class="diff-line modified"><span class="diff-line-marker">~</span><span class="diff-line-num">' + modNum + '</span><span class="diff-line-content">' + (wd.modHtml || "&nbsp;") + "</span></div>";
      } else if (line.type === "removed") {
        origNum++;
        html += '<div class="diff-line removed"><span class="diff-line-marker">\u2212</span><span class="diff-line-num">' + origNum + '</span><span class="diff-line-content">' + escHtml(line.textA) + "</span></div>";
      } else if (line.type === "added") {
        modNum++;
        html += '<div class="diff-line added"><span class="diff-line-marker">+</span><span class="diff-line-num">' + modNum + '</span><span class="diff-line-content">' + escHtml(line.textB) + "</span></div>";
      }
    }
    i.innerHTML = html;
  }

  // ── Set result icon state ────────────────────────────────────────────
  function setIconState(state) {
    resultIconWrap.className = "result-icon-wrap " + state;
    if (state === "identical") {
      resultIconWrap.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/><polyline points="9 12 11 14 15 10"/></svg>';
    } else {
      resultIconWrap.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>';
    }
  }

  // ── Compare button handler ───────────────────────────────────────────
  n.addEventListener("click", function () {
    var textA = e.value,
      textB = t.value;

    if (!textA.trim() && !textB.trim()) {
      showToast("Please enter text in both fields", "error");
      setStatus("error");
      return;
    }

    setStatus("processing");

    var startTime = performance.now();

    // Normalize trailing newlines to prevent false added/removed lines
    var normA = textA.replace(/\n+$/, ""),
      normB = textB.replace(/\n+$/, "");
    var linesA = normA.split("\n"),
      linesB = normB.split("\n");

    var lcsResult = lcs(linesA, linesB);
    var flatDiff = buildFlatDiff(linesA, linesB, lcsResult);
    var paired = pairLines(flatDiff);

    var endTime = performance.now();
    var elapsed = endTime - startTime;

    var added = 0,
      removed = 0,
      unchanged = 0,
      modified = 0;
    for (var k = 0; k < paired.length; k++) {
      if (paired[k].type === "added") added++;
      else if (paired[k].type === "removed") removed++;
      else if (paired[k].type === "modified") modified++;
      else unchanged++;
    }

    var totalWords = countWords(textA) + countWords(textB);
    var similarity = calcSimilarity(textA, textB);
    var isIdentical = added === 0 && removed === 0 && modified === 0;
    var totalChanges = added + removed + modified;

    lastDiffResult = {
      paired: paired,
      added: added,
      removed: removed,
      modified: modified,
      unchanged: unchanged,
      similarity: similarity,
      isIdentical: isIdentical,
      elapsed: elapsed,
      totalWords: totalWords,
      totalLines: linesA.length + linesB.length,
      textA: textA,
      textB: textB
    };

    // Populate summary
    statSimilarityWords.textContent = totalWords;
    statLinesCompared.textContent = unchanged + added + removed + modified;
    statChanged.textContent = totalChanges;
    similarityPct.textContent = similarity + "%";
    similarityFill.style.width = similarity + "%";

    // Populate stats
    statAdded.textContent = added;
    statRemoved.textContent = removed;
    statModified.textContent = modified;
    statUnchanged.textContent = unchanged;

    // Set banner
    if (isIdentical) {
      resultHeading.textContent = "No Differences Found";
      resultSub.textContent = "Both texts are identical. No additions, removals, or modifications were detected.";
      setIconState("identical");
      summaryStatus.className = "summary-status identical";
      summaryStatus.textContent = "Identical";
    } else {
      resultHeading.textContent = "Comparison Complete";
      resultSub.textContent = "Here are the differences between your texts.";
      setIconState("success");
      summaryStatus.className = "summary-status completed";
      summaryStatus.textContent = "Completed";
    }

    // Render panels
    renderSideBySide(paired);
    renderUnified(paired);

    // Show results, hide input actions
    actionBar.style.display = "none";
    showResults();
    setStatus("done");
    a.scrollIntoView({ behavior: "smooth", block: "start" });
  });

  // ── Reset button ─────────────────────────────────────────────────────
  function resetAll() {
    e.value = "";
    t.value = "";
    hideResults();
    actionBar.style.display = "";
    setStatus("ready");
    lastDiffResult = null;
    originalLines.innerHTML = "";
    modifiedLines.innerHTML = "";
    i.innerHTML = "";
    originalLineCount.textContent = "0 lines";
    modifiedLineCount.textContent = "0 lines";
    statSimilarityWords.textContent = "--";
    statLinesCompared.textContent = "--";
    statChanged.textContent = "--";
    similarityPct.textContent = "--";
    similarityFill.style.width = "0";
    statAdded.textContent = "0";
    statRemoved.textContent = "0";
    statModified.textContent = "0";
    statUnchanged.textContent = "0";
  }

  d.addEventListener("click", function () {
    resetAll();
    e.focus();
  });

  // ── Copy button ──────────────────────────────────────────────────────
  o.addEventListener("click", function () {
    if (!lastDiffResult) return;
    var paired = lastDiffResult.paired;
    var text = "";
    for (var k = 0; k < paired.length; k++) {
      var line = paired[k];
      if (line.type === "unchanged") {
        text += "  " + line.textA + "\n";
      } else if (line.type === "modified") {
        text += "- " + line.textA + "\n";
        text += "+ " + line.textB + "\n";
      } else if (line.type === "removed") {
        text += "- " + line.textA + "\n";
      } else if (line.type === "added") {
        text += "+ " + line.textB + "\n";
      }
    }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(function () {
        showToast("Copied to clipboard", "success");
      }).catch(function () {
        fallbackCopy(text);
      });
    } else {
      fallbackCopy(text);
    }
  });

  function fallbackCopy(text) {
    var ta = document.createElement("textarea");
    ta.value = text;
    ta.style.position = "fixed";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.select();
    try {
      document.execCommand("copy");
      showToast("Copied to clipboard", "success");
    } catch (err) {
      showToast("Failed to copy", "error");
    }
    document.body.removeChild(ta);
  }

  // ── Download report ──────────────────────────────────────────────────
  downloadBtn.addEventListener("click", function () {
    if (!lastDiffResult) return;
    var r = lastDiffResult;
    var text = "=== GoToolly Text Comparison Report ===\n\n";
    text += "Similarity: " + r.similarity + "%\n";
    text += "Words Compared: " + r.totalWords + "\n";
    text += "Lines Compared: " + (r.unchanged + r.added + r.removed + r.modified) + "\n";
    text += "Lines Added: " + r.added + "\n";
    text += "Lines Removed: " + r.removed + "\n";
    text += "Lines Modified: " + r.modified + "\n";
    text += "Lines Unchanged: " + r.unchanged + "\n";
    text += "Processing Time: " + (r.elapsed < 1 ? "<1ms" : r.elapsed < 1000 ? Math.round(r.elapsed) + "ms" : (r.elapsed / 1000).toFixed(2) + "s") + "\n";
    text += "Algorithm: Longest Common Subsequence (LCS)\n";
    text += "\n========================================\n\n";
    for (var k = 0; k < r.paired.length; k++) {
      var line = r.paired[k];
      if (line.type === "unchanged") {
        text += "  " + line.textA + "\n";
      } else if (line.type === "modified") {
        text += "- " + line.textA + "\n";
        text += "+ " + line.textB + "\n";
      } else if (line.type === "removed") {
        text += "- " + line.textA + "\n";
      } else if (line.type === "added") {
        text += "+ " + line.textB + "\n";
      }
    }
    var blob = new Blob([text], { type: "text/plain;charset=utf-8" });
    var url = URL.createObjectURL(blob);
    var link = document.createElement("a");
    link.href = url;
    link.download = "gotoolly-text-comparison.txt";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
    showToast("Download started", "success");
  });

  // ── Compare another ──────────────────────────────────────────────────
  compareAnotherBtn.addEventListener("click", function () {
    resetAll();
    e.focus();
    window.scrollTo({ top: 0, behavior: "smooth" });
  });

  // ── Init ─────────────────────────────────────────────────────────────
  setStatus("ready");
});
